use depot.locker;

pub fn report() -> String {
    var ax = depot.locker.Locker { label: "ax", weight: 0 };
    var bay = depot.locker.Locker { label: "bay", weight: 0 };
    var cod = depot.locker.Locker { label: "cod", weight: 0 };

    ax = depot.locker.stow(locker: ax, load: 12);
    ax = depot.locker.stow(locker: ax, load: 9);
    bay = depot.locker.stow(locker: bay, load: 30);
    bay = depot.locker.stow(locker: bay, load: 25);
    cod = depot.locker.stow(locker: cod, load: 5);

    [
        ax.label.concat(other: "=").concat(other: ax.weight.to_text()),
        bay.label.concat(other: "=").concat(other: bay.weight.to_text()),
        cod.label.concat(other: "=").concat(other: cod.weight.to_text()),
    ].join(",")
}
